select
order by d.budget asc, d.demand_id desc order by d.budget desc, d.demand_id desc order by (d.deadline is null) desc, d.deadline desc, d.demand_id desc order by (d.deadline is null) asc, d.deadline asc, d.demand_id asc order by d.created_at asc, d.demand_id asc order by d.created_at desc, d.demand_id desc
limit #{limit} offset #{offset}

