update sys_demand
title = #{title}, genre_id = #{genreId}, tags = #{tags}, budget = #{budget}, deadline = #{deadline}, requirement = #{requirement}, contact_info = #{contactInfo}, total_episodes = #{totalEpisodes}, duration_hours = #{durationHours}, escrow_amount = #{escrowAmount}, escrow_status = #{escrowStatus}, update_by = #{updateBy}, updated_at = NOW(), update_time = NOW()
